from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    for r in range(h):
        if len(set(grid[r])) == 1 and 0 < r < h - 1 and h - r - 1 == r:
            a, b = grid[:r], grid[r + 1:]
            break
    else:
        for c in range(w):
            if len({row[c] for row in grid}) == 1 and 0 < c < w - 1 and w - c - 1 == c:
                a = [row[:c] for row in grid]
                b = [row[c + 1:] for row in grid]
                break
        else:
            raise ValueError('equal panels with a uniform divider not found')
    ca = Counter(x for row in a for x in row)
    cb = Counter(x for row in b for x in row)
    common = set(ca) & set(cb)
    # Select the color that is the sparse feature in either panel; backgrounds
    # differ, and the shared foreground color is painted across the output.
    color = max(common, key=lambda x: (min(ca[x], cb[x]), x))
    return [[3 if a[i][j] == color and b[i][j] == color else color
             for j in range(len(a[0]))] for i in range(len(a))]
